from collections import Counter

class Solution:
    def countSubarrays(self, nums: list[int], k: int) -> int:
        ans = 0
        prev = Counter()
        for x in nums:
            cur = Counter()
            cur[x] += 1
            for val, cnt in prev.items():
                cur[val & x] += cnt
            ans += cur[k]
            prev = cur
        return ans

class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
        long long ans = 0;
        unordered_map<int, int> prev;
        for (int x : nums) {
            unordered_map<int, int> cur;
            cur[x]++;
            for (const auto& [val, cnt] : prev) {
                cur[val & x] += cnt;
            }
            if (cur.count(k)) ans += cur[k];
            prev = move(cur);
        }
        return ans;
    }
};

class Solution {
    public long countSubarrays(int[] nums, int k) {
        long ans = 0;
        Map<Integer, Integer> prev = new HashMap<>();
        for (int x : nums) {
            Map<Integer, Integer> cur = new HashMap<>();
            cur.put(x, 1);
            for (Map.Entry<Integer, Integer> e : prev.entrySet()) {
                int nextVal = e.getKey() & x;
                cur.put(nextVal, cur.getOrDefault(nextVal, 0) + e.getValue());
            }
            if (cur.containsKey(k)) ans += cur.get(k);
            prev = cur;
        }
        return ans;
    }
}

var countSubarrays = function(nums, k) {
    let ans = 0;
    let prev = new Map();
    for (const x of nums) {
        const cur = new Map();
        cur.set(x, 1);
        for (const [val, cnt] of prev.entries()) {
            const nextVal = val & x;
            cur.set(nextVal, (cur.get(nextVal) || 0) + cnt);
        }
        if (cur.has(k)) ans += cur.get(k);
        prev = cur;
    }
    return ans;
};
